// Dankook University, Jukjeon Campus (단국대학교 죽전캠퍼스, 용인 수지구). Data is generated by scripts/campuses/dankook/build-package.mjs
// from the pilot (pilot/dankook-jukjeon, round 3): 29 destructible buildings (범정관·퇴계기념중앙도서관·혜당관·석주선기념박물관 detailed,
// 25 generic), 복지관·치과병원 as protected (dental hospital: shield, never damaged), a baked ground with the pilot's ground shader
// (the SKKU port src/campuses/skku/ground-look.js; the pilot's final-materials.js is the same shader as kyunghee's), the place models
// (분수 광장 수반, 들샘길 219단·폭포 수로, 평화의 광장) and the non-destructible context (죽전·보정 apartments, 법화산) fading into the haze.
// Local only until the user approves (registry public: false).
import { WORLD_UNITS_PER_METER, GEO_ORIGIN, DK_PLACEMENTS, DK_BUILDING_BASE, DK_HEIGHT_GRIDS, DK_HEIGHT_RANGE_M, DK_ENV_IDS, DK_ENV_MANIFEST_IDS, DK_LOOK, DK_ZONES, DK_PROVENANCE } from './data.js';
import { DK_FOOTPRINTS } from './footprints.js';
import { DK_PROTECTED } from './protected.js';
import { createSkkuGroundLook } from '../skku/ground-look.js';

const MODEL_IDS = Object.freeze(DK_PLACEMENTS.map(p => p.id));
const asset = file => new URL(`../../../assets/campuses/dankook/${file}`, import.meta.url).href;
const HAZE = '#dde5e8';

export const DANKOOK = Object.freeze({
  id: 'dankook',
  meta: Object.freeze({ school: '단국대학교', campus: '죽전캠퍼스', short: '단국대', modelNoun: '단국대' }),
  geo: Object.freeze({ origin: GEO_ORIGIN, worldUnitsPerMeter: WORLD_UNITS_PER_METER }),
  placements: DK_PLACEMENTS,
  approvedCount: DK_PLACEMENTS.length,
  additionalCount: 0,
  coreIds: Object.freeze(['beomjeong', 'library', 'hyedang', 'museum']),
  startBuildingId: 'beomjeong',
  // Start: from the 분수 광장 (fountain jet in front) up the two granite flights to 범정관's colonnade and dome (photo wc_2_dankook_0).
  // World units (metres x 0.5, z = -N); azimuth -2.36 = seen from the north-west, along the fountain -> 범정관 axis.
  view: Object.freeze({ startFrame: Object.freeze({ min: Object.freeze([-4, -1, -4]), max: Object.freeze([35, 16, 35]), azimuth: -2.36 }) }),
  models: Object.freeze({
    manifests: Object.freeze([
      Object.freeze({ url: asset('manifest.json'), expectedIds: MODEL_IDS }),
      Object.freeze({ url: asset('environment.json'), expectedIds: DK_ENV_MANIFEST_IDS }),
    ]),
    proceduralIds: Object.freeze([]),
    createProceduralSource: () => { throw new Error('No procedural buildings in this campus'); },
    enhanceFacade: () => ({ stats: {}, dispose() {} }),
  }),
  terrain: Object.freeze({ heightGrids: DK_HEIGHT_GRIDS, buildingBase: DK_BUILDING_BASE,
    source: 'Relative terrain estimate (Copernicus GLO-30, building-filled, canopy lowered by an estimate + floor-link / photo level evidence, pilot/dankook-jukjeon); not a survey' }),
  environment: Object.freeze({ provenance: DK_PROVENANCE, sourceNote: 'OSM ground surfaces and surroundings (© OpenStreetMap contributors, ODbL); heights, planting and the place models estimated' }),
  ground: Object.freeze({
    baked: Object.freeze({ envIds: DK_ENV_IDS, castShadow: Object.freeze([]), materialHook: createSkkuGroundLook(DK_LOOK, DK_ZONES),
      fade: Object.freeze({ centre_m: Object.freeze([177.7, -196.5]), near_m: 600, far_m: 1350, colour: HAZE }), playMargin_m: 30,
      source: 'pilot/dankook-jukjeon preview ground + landscape + context, baked' }),
  }),
  // 복지관·치과병원 (dental hospital): never destructible; weapons meet the protective shield (src/protected-buildings.js), own small cache.
  protected: Object.freeze({
    manifestURL: asset('protected/manifest.json'),
    models: DK_PROTECTED,
  }),
  // Hazard tape around every destructible building only (src/engine/hazard-tape.js): none on the hospital or the context.
  hazardTape: Object.freeze({ footprints: DK_FOOTPRINTS }),
  scene: Object.freeze({
    background: HAZE, fog: Object.freeze({ color: HAZE, near: 760, far: 2400 }),
    hemisphere: Object.freeze({ sky: '#eef2f4', ground: '#7d8a78', intensity: 1.3 }),
    sun: Object.freeze({ color: '#fff4e2', intensity: 2.9, position: Object.freeze([-170, 150, 60]), shadowSpan: 260 }),
    floor: Object.freeze({ color: '#c9cbc8', hidden: true, y: DK_HEIGHT_RANGE_M[0] * WORLD_UNITS_PER_METER - .3 }),
  }),
});
export default DANKOOK;
